import React from 'react';

function App() {
  return (
    <div className="min-h-screen bg-purple-200">
      <header className="p-6 bg-purple-800 text-white">
        <h1 className="text-3xl font-bold">Melodic Justice</h1>
        <p>Animation Project Dashboard</p>
      </header>
      <main className="p-6">
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h2 className="text-xl font-semibold mb-4">Welcome to your dashboard</h2>
          <p>Your animation project management system is being set up.</p>
        </div>
      </main>
    </div>
  );
}

export default App;
